---@param TouchTipsTF_ UnityEngine.Transform 
---@param btn_ UnityEngine.UI.Button    
---@param idolLive3D_UIMain_ table
function IdolLive3D_UITouchTips:__init( TouchTipsTF_, btn_, idolLive3D_UIMain_ )

    self.idolLive3D_UIMain = idolLive3D_UIMain_

    local isNeedTouchTips = (table.count(self.idolLive3D_UIMain.touchTipDatas) > 0) and (self.idolLive3D_UIMain.isDemo == false)

    --------
    self.TouchTipsTF = TouchTipsTF_ 
    self.Touch3DDetailsTF = self.TouchTipsTF:Find("3DTouchDetails")
    self.TxtNum = self.TouchTipsTF:Find("TxtNum")
    self.cell = self.Touch3DDetailsTF:Find("Cell")

    self.Imgbg = self.Touch3DDetailsTF:Find("Imgbg")
    self.Tips = self.Touch3DDetailsTF:Find("Tips")
    self.Tips2 = self.Touch3DDetailsTF:Find("Tips2")

    self.Title1 = self.Touch3DDetailsTF:Find("Title1")
    self.Title1Num = self.Title1:Find("TxtDeco/TxtNum")
    ---
    if isNull(self.Title1) or isNull(self.Title1Num) then 
        printError("没找到节点: Title1 或 Title1Num")
    end

    if isNeedTouchTips == false then 
        CfUtils.SetActive( self.TouchTipsTF.gameObject, false )
        return
    end 

    ---
    CfUtils.SetActive( self.TouchTipsTF.gameObject, true )
    for _,tip in pairs(self.idolLive3D_UIMain.touchTipDatas) do 
        local newCellGO = GameObject.Instantiate( self.cell, self.Touch3DDetailsTF )
        CfUtils.SetActive( newCellGO, true )
        tip.transform = newCellGO.transform
        tip.cellEnv = CfUtils.GetLuaScr(newCellGO, "Game.IdolLive3D.IdolLive3D_UITouchTipsCell")
        tip.cellEnv:Init( tip.key, tip.name, checkInt(tip.touchedNum)>0 )
    end

    self:_Draw()
    self.isShow = false
    self.EventPlayAction  = Events.AddListener(IdolLive3D_States.EventPlayAction, Bind(self, self._OnEventPlayAction))
    SetButtonAction(btn_, Bind(self, self._OnClickBtn))


    self.EventGetUITouchTip = Events.AddListener(IdolLive3D_States.EventGetUITouchTip, function( uiTouchTipKey_, retTable_ )
        uiTouchTipKey_ = string.lower(uiTouchTipKey_)
        for _,tip in pairs(self.idolLive3D_UIMain.touchTipDatas) do 
            if string.lower(tip.key) ==  uiTouchTipKey_ then 
                retTable_.ret = tip
                return
            end 
        end 
        retTable_.ret = nil
    end)


end


-- 需手动调用 Delete()
function IdolLive3D_UITouchTips:__delete()
    if self.EventPlayAction then
        Events.RemoveListener(IdolLive3D_States.EventPlayAction, self.EventPlayAction)
        self.EventPlayAction = nil
    end
    if self.EventGetUITouchTip then
        Events.RemoveListener(IdolLive3D_States.EventGetUITouchTip, self.EventGetUITouchTip)
        self.EventGetUITouchTip = nil
    end
end


----------------------------------------------------------

function IdolLive3D_UITouchTips:_Draw()

    local totalNum = table.count(self.idolLive3D_UIMain.touchTipDatas)
    local touchedNum = 0
    for _,e in pairs(self.idolLive3D_UIMain.touchTipDatas) do 
        if e.touchedNum > 0 then 
            touchedNum = touchedNum + 1
        end     
        --e.cellEnv:SwitchState( e.touchedNum > 0 )
    end 

    touchedNum = checkInt(touchedNum)
    totalNum = checkInt(totalNum)

    local offsetMin = self.Imgbg.offsetMin

    if touchedNum == 0 then 
        CfUtils.SetActive( self.Tips, true )
        CfUtils.SetActive( self.Tips2, false )
        offsetMin.y = -24

    elseif touchedNum < totalNum then 
        CfUtils.SetActive( self.Tips, false )
        CfUtils.SetActive( self.Tips2, true )
        offsetMin.y = -64
    else 
        CfUtils.SetActive( self.Tips, false )
        CfUtils.SetActive( self.Tips2, false )
        offsetMin.y = -24
    end 

    self.Imgbg.offsetMin = offsetMin

    ---
    for _,e in pairs(self.idolLive3D_UIMain.touchTipDatas) do   
        if touchedNum == 0 then 
            CfUtils.SetActive( e.transform.gameObject, false )
        else 
            CfUtils.SetActive( e.transform.gameObject, true )
            e.cellEnv:SwitchState( e.touchedNum > 0 )
        end
    end 

    CfUtils.FillText( self.TxtNum, string.format('<color=#00FFFC><size=32>%d</size></color>/%d', touchedNum, totalNum ) )
    CfUtils.FillText( self.Title1Num, string.format('<color=#FF009C><size=32>%d</size></color>/%d', touchedNum, totalNum ) )
end




function IdolLive3D_UITouchTips:_OnClickBtn()
    --printError("  IdolLive3D_UITouchTips:_OnClickBtn ")
    self.isShow = not self.isShow
    if self.isShow == true then 
        CfUtils.SetCanvasGroupAlpha( self.Touch3DDetailsTF.gameObject, 1 )
        CfUtils.PlayAnimation(self.Touch3DDetailsTF.gameObject, "PredownloadEntryMainDialog_BtnInteraction_3DTouchDetails_Go", false)
    else 
        CfUtils.SetCanvasGroupAlpha( self.Touch3DDetailsTF.gameObject, 0 )
    end
end



---@return table or nil
function IdolLive3D_UITouchTips:_FindTip( key_ )
    for _,tip in pairs(self.idolLive3D_UIMain.touchTipDatas) do 
        if string.lower(tip.key) == string.lower(key_) then 
            return tip
        end 
    end 
    return nil
end



function IdolLive3D_UITouchTips:_OnEventPlayAction( params )

    local pKey = tostring(params.key)
    --printError( "call; " .. pKey )
    local tip = self:_FindTip(pKey)
    if isNull(tip) then 
        print( "配表 Live3DTouchTipsVO 中没找到 key: " .. pKey .. "; 可能有问题" )
        return
    end 
    ---
    tip.touchedNum = tip.touchedNum + 1
    self:_Draw()
    ---  
    local deepTimes = IdolLive3D_Utils.GetPlayerDojoDeepTimes(self.idolLive3D_UIMain.cardSkinId)    
    deepTimes[pKey] = tip.touchedNum
end




return IdolLive3D_UITouchTips
